{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "In healthy subjects, pethidine had an absolute oral bioavailability of 0.52 (0.47–0.61), clearly above the 20% threshold."
    },
    {
      "card_ids": ["C10"],
      "claim": "In healthy male volunteers, solifenacin showed a mean absolute oral bioavailability of 88% after oral versus IV administration, supporting high bioavailability."
    },
    {
      "card_ids": ["C06"],
      "claim": "In normal subjects, encainide had an absolute oral bioavailability of 32 ± 7%, above the 20% threshold."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All representative numeric records and the broader evidence set show oral bioavailability values above 20% in healthy or relevant populations; no affirmative low-bioavailability evidence was supplied, so the prediction is high.",
  "evidence_gaps": [
    "Some records were obtained in disease populations such as cirrhosis or hepatic disease and may not reflect normal physiology, but they still support F ≥ 20%.",
    "A few qualitative reports of 'poor' or 'low' bioavailability were discounted because they lacked numeric threshold-relevant measurements."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C23", "C10", "C06"],
  "revision_action": "initial",
  "supportive_card_ids": ["C23", "C10", "C06"]
}

